// Game of Life scenes for the slides, generated from the Lean data of LeanTheory/Theory/Life
// (scripts in the session scratchpad: leandata.py, build.py, build2.py, lpmach.py).
// Coordinates: x right, y DOWN.  Lean `ofRows x0 y0 rows` already uses this convention
// (cell (x0 + j, y0 + i) alive iff bit j of rows[i]; LSB = leftmost; rows top to bottom),
// so every cell here is the Lean cell unchanged (no flip, no shift).
// rle + offset: standard Life RLE; the FIRST row of the RLE body is row offset.y, its first
// column is offset.x (do not skip or shift the first row). window.GOL_decodeRLE(rle, offset)
// below returns the [x, y] cells.
window.GOL_decodeRLE = function (rle, off) {
  const body = rle.slice(rle.indexOf("\n") + 1); const out = [];
  let x = off.x, y = off.y, num = "";
  for (const ch of body) {
    if (ch >= "0" && ch <= "9") { num += ch; continue; }
    const n = num ? parseInt(num, 10) : 1; num = "";
    if (ch === "b") x += n;
    else if (ch === "o") { for (let i = 0; i < n; i++) out.push([x + i, y]); x += n; }
    else if (ch === "$") { y += n; x = off.x; }
    else if (ch === "!") break;
  }
  return out;
};
